#!/usr/bin/env node
// SPDX-License-Identifier: GPL-3.0-or-later
'use strict';

/**
 * Builds dist/setup.sql: every migration in one file, for pasting into the
 * Supabase SQL Editor when installing the Supabase CLI is not an option.
 *
 * The result runs in a single transaction and is idempotent: each migration is
 * applied only if fulla.schema_migrations does not already list it, so running
 * the file again after an upgrade applies just the new ones.
 *
 * Usage: node supabase/scripts/bundle.js [output path]
 */

const fs = require('node:fs');
const path = require('node:path');

const MIGRATIONS = path.join(__dirname, '..', 'migrations');

const BOOTSTRAP = `create schema if not exists fulla;
create table if not exists fulla.schema_migrations (
  filename   text primary key,
  applied_at timestamptz not null default now()
);
alter table fulla.schema_migrations enable row level security;
revoke all on fulla.schema_migrations from public, anon, authenticated;
`;

function migrations() {
  return fs.readdirSync(MIGRATIONS).filter((f) => /^\d{4}_.+\.sql$/.test(f)).sort();
}

function bundle() {
  const parts = [
    '-- Fulla database setup. Generated by supabase/scripts/bundle.js; do not edit.',
    '-- Paste into the Supabase SQL Editor and run. Safe to run again.',
    '',
    'begin;',
    BOOTSTRAP,
  ];
  for (const file of migrations()) {
    const sql = fs.readFileSync(path.join(MIGRATIONS, file), 'utf8');
    const tag = `$fulla_${file.slice(0, 4)}$`;
    if (sql.includes(tag)) throw new Error(`${file} contains the quoting tag ${tag}`);
    parts.push(`-- ${file}`);
    parts.push(`do $fulla_bundle$
begin
  if not exists (select 1 from fulla.schema_migrations where filename = '${file}') then
    execute ${tag}
${sql}
${tag};
    insert into fulla.schema_migrations (filename) values ('${file}');
  end if;
end
$fulla_bundle$;
`);
  }
  parts.push('commit;', '');
  return parts.join('\n');
}

if (require.main === module) {
  const out = process.argv[2] || path.join(__dirname, '..', '..', 'dist', 'setup.sql');
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, bundle());
  console.log(`wrote ${path.relative(process.cwd(), out)} (${migrations().length} migrations)`);
}

module.exports = { bundle, migrations, BOOTSTRAP };
